<span class="line"><span style="color:#DCDCAA;">write</span><span style="color:#CE9178;"> to</span><span style="color:#CE9178;"> dir</span><span style="color:#D4D4D4;"> [/opt/dmdbms/data/DAMENG].</span></span>
